import hashlib,json,pathlib,shutil,sys
baseline,output=map(pathlib.Path,sys.argv[1:])
names=(('native-song.wav','native-song.wav'),('native-song.frames.json','native-song.frames.json'),('native-song.writes.json','native-song.writes.json'),('conversion.json','conversion.json'),('verification.json','verification.json'),('export/candidate.sid','export/reference.sid'))
errors=[];selected=None
for receipt_name in ('completed-run.json','run.json'):
    try:
        receipt_path=baseline/receipt_name
        receipt=json.loads(receipt_path.read_text())
        if receipt['status']!='completed':raise ValueError('receipt is not completed')
        stages=[item for item in receipt['stages'] if item['id']=='candidate' and item['status'] in ('completed','reused')]
        if len(stages)!=1:raise ValueError('expected one successful candidate stage')
        stage=stages[0]
        source=baseline/'cache'/'candidate'/stage['cacheKey']/pathlib.Path(stage['attemptDirectory']).name/'song'
        if not source.resolve().is_relative_to((baseline/'cache'/'candidate').resolve()):raise ValueError('candidate artifact path leaves the baseline cache')
        artifacts=[]
        for name,destination in names:
            path=source/name
            matches=[item for item in receipt['artifacts'] if item['stageId']=='candidate' and item['relativePath']=='song/'+name]
            if len(matches)!=1 or path.is_symlink() or hashlib.sha256(path.read_bytes()).hexdigest()!=matches[0]['sha256']:raise ValueError('artifact differs from receipt: '+name)
            artifacts.append((path,destination,matches[0]['sha256']))
        if artifacts[0][2]!='e5698fc525b4f884ffe4b8fdab26e929e585a4c199c0baa82dd0d59866b13154':raise ValueError('receipt does not describe the frozen tonal full WAV')
        verification=json.loads((source/'verification.json').read_text())
        if verification['pcm']['sha256']!=artifacts[0][2] or verification['audit']['sourceSha256']!=artifacts[-1][2]:raise ValueError('Baseline full-render verification does not bind this WAV and SID')
        sidecar=source/'native-song.wav.registers.tsv'
        if sidecar.is_symlink() or not sidecar.is_file():raise ValueError('Baseline full-render snapshot sidecar is missing')
        artifacts.append((sidecar,'native-song.wav.registers.tsv',hashlib.sha256(sidecar.read_bytes()).hexdigest()))
        selected=(receipt_name,receipt_path,receipt,artifacts);break
    except (OSError,ValueError,KeyError,TypeError) as error:errors.append(receipt_name+': '+str(error))
if selected is None:raise ValueError('No intact completed baseline receipt: '+str(errors)+'. Restore its declared inputs, then run python3 scripts/listening-package.py config/listening/axel-f-full-master-palette.json --output build/axel-f-full-master-palette')
receipt_name,receipt_path,receipt,artifacts=selected
output.mkdir();reports=[]
for source,destination,digest in artifacts:
    target=output/destination;target.parent.mkdir(parents=True,exist_ok=True);shutil.copyfile(source,target)
    if hashlib.sha256(target.read_bytes()).hexdigest()!=digest:raise ValueError('Copied baseline artifact differs: '+destination)
    reports.append(dict(sourcePath=str(source),destination=destination,sha256=digest))
shutil.copyfile(receipt_path,output/'reference-input-receipt.json')
(output/'reference-reuse.json').write_text(json.dumps(dict(schemaVersion=1,sourceReceipt=str(receipt_path),selectedReceiptName=receipt_name,sourceReceiptSha256=hashlib.sha256(receipt_path.read_bytes()).hexdigest(),files=reports,earlierReceiptFailures=errors,freshBaselineRender=False,fullRenderSnapshotSidecarPinnedAtImport=True,fullRenderSnapshotSidecarOriginallyDeclaredInReceipt=False,scope='Receipt-driven reuse. Candidate cache key and attempt directory come from the completed receipt, so a regenerated baseline needs no hardcoded UUID. The whole baseline directory is a declared input, including every source artifact.'),indent=2)+chr(10))
